/** Things no open-access source provides — any number here is ours. */
export const GAPS = [
  "Rolls or lie-downs per hour that mean colic.",
  "How many hours before a natural colic eating, droppings, lying or activity change.",
  "The hours of the day when colic most often starts.",
  "A time limit for lying down, or for lying flat on the side.",
  "A rhythm or minimum number of cycles for weaving.",
  "How long each urination lasts, or how much is passed each time.",
  "A 'no manure for X hours' alarm threshold.",
  "An eye-temperature fever threshold (eye readings do not reliably track rectal temperature, and the offset depends on camera and distance).",
  "What a sudden drop in a stereotypy means.",
  "Anything on thermal images of fresh urine or manure.",
  "Lying and sleep of horses in heat above 30 °C.",
  "Whether drinking (swallowing) can be seen on stall video.",
  "Behaviour norms for Marwari, Kathiawari or Indian country-bred horses, or for Indian Army horses.",
  "Peer-reviewed validation of commercial colic alarms.",
];

export function knowledge() {
  return { compiled: "2026-10-04", groups: GROUPS, patterns: PATTERNS, sources: SOURCES, gaps: GAPS };
}

/** The pattern a footage label belongs to, for tooltips. */
export function patternForLabel(key) {
  return PATTERNS.find((p) => p.label === key) || null;
}
